statement:
You are handed a string `num` made only of digits. Cut all of it, left to right, into consecutive pieces and read each piece as a non-negative integer. The resulting list `f` counts as Fibonacci-like when:

- it holds at least 3 numbers;
- every number is below 2^31, so it fits in a signed 32-bit integer;
- from the third number onward, each number is the sum of the two right before it (`f[i] + f[i + 1] == f[i + 2]`).

A piece may start with the digit `0` only when the piece is exactly `"0"`. Return such a list built from `num`; when several splits work, any one of them is accepted. When no split works, return an empty list.

checker:
function check(input, actual, expected) {
  const num = input[0];
  if (!Array.isArray(actual)) return false;
  if (actual.length === 0) return Array.isArray(expected) && expected.length === 0;
  if (actual.length < 3) return false;
  if (actual.some(v => !Number.isInteger(v) || v < 0 || v > 2147483647)) return false;
  for (let i = 2; i < actual.length; i++) {
    if (actual[i - 2] + actual[i - 1] !== actual[i]) return false;
  }
  // String(v) never has leading zeros, so this also rules out pieces like "01".
  return actual.map(String).join('') === num;
}

validator:
function validate([num]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 200) return 'num needs 1 to 200 characters.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain digits only.';
  return null;
}

