function splitIntoFibonacci(num) {
  const LIMIT = 2 ** 31 - 1;
  const sequence = [];

  function backtrack(start) {
    if (start === num.length) {
      return sequence.length >= 3;
    }
    let value = 0;
    for (let end = start; end < num.length; end++) {
      if (end > start && num[start] === '0') {
        break;
      }
      value = value * 10 + Number(num[end]);
      if (value > LIMIT) {
        break;
      }
      const size = sequence.length;
      if (size >= 2 && value > sequence[size - 1] + sequence[size - 2]) {
        break;
      }
      if (size < 2 || value === sequence[size - 1] + sequence[size - 2]) {
        sequence.push(value);
        if (backtrack(end + 1)) {
          return true;
        }
        sequence.pop();
      }
    }
    return false;
  }

  return backtrack(0) ? sequence : [];
}

