function splitIntoFibonacci(num) {
  const n = num.length;
  const ok = (s) => s.length > 0 && (s === '0' || s[0] !== '0') && BigInt(s) < 2n ** 31n;
  for (let i = 1; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = num.slice(0, i), b = num.slice(i, j);
      if (!ok(a) || !ok(b)) continue;
      const list = [Number(a), Number(b)];
      let rest = num.slice(j);
      while (rest.length > 0) {
        const next = list[list.length - 1] + list[list.length - 2];
        const text = String(next);
        if (next >= 2 ** 31 || !rest.startsWith(text)) break;
        list.push(next);
        rest = rest.slice(text.length);
      }
      if (rest.length === 0 && list.length >= 3) return list;
    }
  }
  return [];
}

