function generate(rand, size) {
  const LIMIT = 2 ** 31 - 1;
  const maxLen = size === 'large' ? 200 : 14;
  const int = (k) => Math.floor(rand() * k);
  const mode = int(4);
  if (mode === 0) {
    const len = size === 'large' ? 150 + int(51) : 1 + int(maxLen);
    let s = '';
    for (let i = 0; i < len; i++) s += String(rand() < 0.15 ? 0 : int(10));
    return [s];
  }
  if (mode === 1 && size === 'small') {
    return ['0'.repeat(1 + int(8))];
  }
  // Build a real Fibonacci-like chain, then sometimes damage one digit.
  const pick = () => { const r = rand(); return r < 0.2 ? 0 : r < 0.6 ? int(10) : int(size === 'large' ? 100000 : 200); };
  const list = [pick(), pick()];
  let s = String(list[0]) + String(list[1]);
  for (;;) {
    const next = list[list.length - 1] + list[list.length - 2];
    if (next > LIMIT || s.length + String(next).length > maxLen) break;
    list.push(next);
    s += String(next);
  }
  if (rand() < 0.4 && s.length > 1) {
    const at = int(s.length);
    s = s.slice(0, at) + String(int(10)) + s.slice(at + 1);
  }
  return [s];
}
